ALTER TABLE "AlertConfig" ADD COLUMN "moderationEnabled" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "ModerationPolicy" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"name" TEXT NOT NULL,"blockedWords" TEXT[],"blockLinks" BOOLEAN NOT NULL DEFAULT true,"minimumInCents" BIGINT NOT NULL DEFAULT 0,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ModerationPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ModerationItem" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"supporterName" TEXT,"content" TEXT NOT NULL,"amountInCents" BIGINT,"status" TEXT NOT NULL DEFAULT 'PENDING',"decisionReason" TEXT,"decidedById" UUID,"decidedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ModerationItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TtsConfig" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"voice" TEXT NOT NULL DEFAULT 'pt-BR-default',"minimumInCents" BIGINT NOT NULL DEFAULT 500,"maximumCharacters" INTEGER NOT NULL DEFAULT 200,"paused" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TtsConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TtsJob" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"moderationItemId" UUID NOT NULL,"text" TEXT NOT NULL,"voice" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TtsJob_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ModerationItem_sourceType_sourceId_key" ON "ModerationItem"("sourceType","sourceId"); CREATE INDEX "ModerationPolicy_organizationId_enabled_idx" ON "ModerationPolicy"("organizationId","enabled"); CREATE INDEX "ModerationItem_organizationId_status_createdAt_idx" ON "ModerationItem"("organizationId","status","createdAt"); CREATE UNIQUE INDEX "TtsConfig_organizationId_key" ON "TtsConfig"("organizationId"); CREATE UNIQUE INDEX "TtsJob_moderationItemId_key" ON "TtsJob"("moderationItemId"); CREATE INDEX "TtsJob_organizationId_status_createdAt_idx" ON "TtsJob"("organizationId","status","createdAt");
ALTER TABLE "ModerationPolicy" ADD CONSTRAINT "ModerationPolicy_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ModerationItem" ADD CONSTRAINT "ModerationItem_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TtsConfig" ADD CONSTRAINT "TtsConfig_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TtsJob" ADD CONSTRAINT "TtsJob_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TtsJob" ADD CONSTRAINT "TtsJob_moderationItemId_fkey" FOREIGN KEY ("moderationItemId") REFERENCES "ModerationItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
